mapper.select:
SELECT device.ID, device.PARENT_ID, device.NAME, device.VOLTAGE, device.TYPE, device.BAY_NAME, device.PATTERN_ID, device.SIGNAL_TEMPLATE_ID, temp.name as SIGNAL_TEMPLATE_NAME FROM "DEVICE_INFO" device LEFT JOIN SIGNAL_TEMPLATE temp on temp.id = device.signal_template_id
AND VOLTAGE = #{voltage}
AND TYPE = #{type}
AND NAME LIKE '%' || #{name} || '%'
AND ID = #{id}
ORDER BY VOLTAGE, TYPE, NAME
